        self.val = val
        self.left = left
        self.right = right

def delete_node(root, key):
    if not root:
        return None
    if key < root.val:
        root.left = delete_node(root.left, key)
    elif key > root.val:
        root.right = delete_node(root.right, key)
    else:
        if not root.left:
            return root.right
        if not root.right:
            return root.left
        curr = root.right
        while curr.left:
            curr = curr.left
        root.val = curr.val
        root.right = delete_node(root.right, curr.val)
    return root

