import heapq

def dijkstra(graph, start, target):
    pq = [(0, start, [start])]
    visited = set()
    while pq:
        cost, u, path = heapq.heappop(pq)
        if u in visited:
            continue
        visited.add(u)
        if u == target:
            return cost, path
        for v, w in graph.get(u, []):
            if v not in visited:
                heapq.heappush(pq, (cost + w, v, path + [v]))
    return float('inf'), []

